// HotelClash game engine — the single source of truth for the game rules.
//
// It runs in two places with identical results:
//   - in the browser, so the game is responsive and playable offline;
//   - on the server, which replays every player's action log and whose result
//     is authoritative (leaderboards, saves, rewards).
//
// The source of truth lives in hotel-clash-api/engine. The web app gets a
// generated copy (npm run engine:sync in the web repo) — never edit that copy.
//
// Rules for code in this folder: no Math.random/Date.now/Math.pow, no I/O, no
// globals. Everything that affects the simulation must live in the state.
import { canonicalJson, hashString } from './math.js';
import { createInitialState, makeContext, stateFromLegacy } from './core.js';
import { runDay, postProcess } from './tick.js';
import { ACTION_HANDLERS, recordAwayTime } from './actions.js';
import { MIN_TICK_INTERVAL_MS } from './data.js';

export * as data from './data.js';
export { RANDOM_EVENTS } from './events.js';
export * as insights from './insights.js';

/** Bump when a rule change makes old action logs replay differently. */
export const ENGINE_VERSION = 12; // 12: away earnings (CLAIM_AWAY_EARNINGS)

/** Tolerated backwards clock jump (e.g. an NTP correction) before rejecting. */
const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;

export const ACTION_TYPES = ['TICK', ...Object.keys(ACTION_HANDLERS)];

export function newGame({ seed, hotelName, hotelType, t = 0 } = {}) {
  return createInitialState({ seed, hotelName, hotelType, t });
}

export { stateFromLegacy };

/**
 * Apply one action to `S` in place. Handlers validate before mutating, so a
 * rejected action leaves `S` unchanged.
 * @returns {{ ok: boolean, error?: string, effects: object[] }}
 */
export function applyActionInPlace(S, action) {
  const t = Number(action && action.t);
  if (!action || typeof action.type !== 'string') return { ok: false, error: 'invalid_action', effects: [] };
  if (!Number.isFinite(t) || t <= 0) return { ok: false, error: 'invalid_timestamp', effects: [] };
  if (t < S.clock.lastT - MAX_CLOCK_SKEW_MS) return { ok: false, error: 'clock_went_backwards', effects: [] };
  const now = Math.max(t, S.clock.lastT);

  // A bankrupt hotel is closed: only coins bought with real money still arrive
  // (the server carries them into the player's next hotel).
  if (S.gameOver && action.type !== 'RECEIVE_COINS') return { ok: false, error: 'game_over', effects: [] };

  const G = makeContext(S, now);
  let result;
  if (action.type === 'TICK') {
    if (S.clock.lastTickT && now - S.clock.lastTickT < MIN_TICK_INTERVAL_MS) {
      return { ok: false, error: 'tick_too_fast', effects: [] };
    }
    S.clock.lastTickT = now;
    runDay(G);
    result = { ok: true };
  } else {
    const handler = Object.prototype.hasOwnProperty.call(ACTION_HANDLERS, action.type) ? ACTION_HANDLERS[action.type] : null;
    if (!handler) return { ok: false, error: 'unknown_action', effects: [] };
    result = handler(G, action);
  }
  if (result.ok) {
    recordAwayTime(G, now - S.clock.lastT);
    S.clock.lastT = now;
    postProcess(G);
  }
  return { ...result, effects: G.effects };
}

/** Pure version for UI code: returns a new state. */
export function applyAction(state, action) {
  const S = structuredClone(state);
  const result = applyActionInPlace(S, action);
  return { ...result, state: result.ok ? S : state };
}

/**
 * Replay a batch of actions. Used by the server to verify a client's log and
 * by the client to rebase pending actions on top of a server state.
 */
export function replay(state, actions, { collectEffects = false } = {}) {
  const S = structuredClone(state);
  const rejected = [];
  const effects = [];
  for (const action of actions) {
    const r = applyActionInPlace(S, action);
    if (!r.ok) rejected.push({ seq: action.seq, type: action.type, error: r.error });
    if (collectEffects) effects.push(...r.effects);
  }
  return { state: S, rejected, effects };
}

export function hashState(state) {
  return hashString(canonicalJson(state));
}

/** Metrics used for leaderboards and save listings. */
export function summarize(S) {
  const guests = S.guests || [];
  return {
    hotelName: S.hotelName,
    hotelType: S.hotelType,
    day: S.day,
    money: S.money,
    credits: S.credits,
    reputation: S.reputation,
    marketShare: S.marketShare,
    hotelLevel: S.hotelLevel,
    guestCount: guests.length,
    guestSatisfaction: guests.length ? guests.reduce((s, g) => s + g.happiness, 0) / guests.length : 0,
    roomCount: S.rooms.length,
    staffCount: S.staff.length,
    totalGuestsServed: S.totalGuestsServed,
  };
}
